package com.systemcallmobile.call
import android.app.*;import android.content.Intent;import android.content.pm.ServiceInfo;import android.os.*;import androidx.core.app.NotificationCompat
class CallForegroundService:Service(){companion object{const val CHANNEL_ID="systemcall_active_call";const val NOTIFICATION_ID=9001}override fun onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O)getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel(CHANNEL_ID,"Активный звонок",NotificationManager.IMPORTANCE_LOW))}override fun onStartCommand(intent:Intent?,flags:Int,startId:Int):Int{val n=NotificationCompat.Builder(this,CHANNEL_ID).setContentTitle("SystemCall").setContentText("Идёт видеозвонок").setSmallIcon(android.R.drawable.presence_video_online).setOngoing(true).setCategory(NotificationCompat.CATEGORY_CALL).build();if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.R)startForeground(NOTIFICATION_ID,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_CAMERA or ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE) else startForeground(NOTIFICATION_ID,n);return START_STICKY}override fun onBind(intent:Intent?):IBinder?=null}
